package com.shopsphere.rmi.client;import com.shopsphere.rmi.remote.InventoryService;import java.rmi.Naming;public class RMIClient{public static void main(String[]x){try{InventoryService s=(InventoryService)Naming.lookup("rmi://localhost/InventoryService");System.out.println(s.getProduct(1));System.out.println("Stock="+s.getStock(1));System.out.println("Update="+s.updateStock(1,2));System.out.println("New Stock="+s.getStock(1));}catch(Exception e){e.printStackTrace();}}}
